body.la-ld .nt-chon, body.la-ld .nt-nhac, body.la-ld #ttTatCa, body.la-ld .pTT, body.la-ld .pNV, body.la-ld .pGC, body.la-ld .pLuu, body.la-ld .pKQ,
body.la-ld .dlXuLy, body.la-ld .cnDuyet, body.la-ld .hddDuyet, body.la-ld .hddTuChoi, body.la-ld .hddLink, body.la-ld .hddGhi,
body.la-ld .nghiNut, body.la-ld .doiNut, body.la-ld .doiYK, body.la-ld #fNghi, body.la-ld #fDoi, body.la-ld #tknDangCho, body.la-ld #nbTKCho { display:none !important; }
