/* v70: bảng nộp tiền gọn */
.bn-tom { border:1px solid var(--vien); border-radius:14px; background:#f8fafc; padding:12px 14px; display:grid; gap:6px; }
.bn-tom-ten { display:flex; flex-direction:column; gap:2px; min-width:0; } .bn-tom-ten b { font-size:17px; line-height:1.3; } .bn-tom-ten span { color:var(--xam); font-size:13.5px; overflow-wrap:anywhere; }
.bn-tom-tien { display:flex; align-items:baseline; justify-content:space-between; gap:10px; border-top:1px dashed var(--vien); padding-top:6px; } .bn-tom-tien span { color:var(--xam); font-weight:600; }
.bn-tom-tien b.tien-hd { color:var(--do); font-size:22px; font-weight:800; }
.bn-ho { display:flex; gap:8px; align-items:flex-start; margin-top:10px; padding:9px 12px; border-radius:12px; background:var(--xanh2); color:var(--xanh-dam); font-size:14px; line-height:1.45; }
.bn-canh ul li + li { margin-top:3px; }
.bn-lh { margin-top:14px; border:1px solid var(--vien); border-radius:16px; padding:12px; gap:10px; }
.bn-lh-dau { display:flex; align-items:center; gap:8px; flex-wrap:wrap; font-weight:800; color:var(--xanh-dam); font-size:16px; } .bn-lh-dau span { font-weight:600; color:var(--xam); font-size:13.5px; }
.bn-lh .bn-cb { flex-wrap:wrap; }
.bn-cb-nut { display:flex; gap:8px; flex:1 1 100%; }
.bn-cb-nut a { display:inline-flex; align-items:center; justify-content:center; gap:6px; min-height:46px; }
.bn-cb-nut a.zalo { flex:1; font-size:15px; }
.bn-cb-nut a.goi2 { flex:0 0 auto; padding:9px 16px; }
.bn-goilai { color:var(--xanh); font-weight:700; text-align:center; font-size:14px; }
.nt-ht { display:inline-flex; align-items:center; gap:4px; font-weight:800; font-size:12.5px; padding:2px 9px; border-radius:999px; }
.nt-ht.qr { background:#e3f2fd; color:#0d47a1; } .nt-ht.zl { background:#e8f5e9; color:#1b5e20; } .nt-ht.goi { background:#fff3e0; color:#e65100; }
/* v70b: gọn hơn – nút nhỏ, lưu ý 3 dòng, QR + liên hệ sát nhau */
.chu-do-dam, .bn-canh .chu-do-dam { color:#c62828; font-weight:800; }
.bn-canh.gon { margin:10px 0; padding:9px 12px; font-size:13.5px; line-height:1.45; border-width:1.5px; }
.bn-canh.gon ul { margin:4px 0 0; padding-left:16px; } .bn-canh.gon li + li { margin-top:2px; }
.bn-dongy.gon { padding:9px 12px; font-size:14.5px; align-items:center; } .bn-dongy.gon input { width:20px; height:20px; }
#bangNop .bn-qr { margin-top:10px; padding:10px; gap:8px; border-width:1.5px; }
#bangNop .bn-qr-dau { font-size:15px; } #bangNop .bn-qr-dau span { font-size:13px; }
#bangNop .bn-qr-than { gap:10px; } #bangNop .bn-qr-anh { width:170px; height:170px; }
#bangNop .bn-qr-tt { font-size:13px; gap:2px 8px; }
#bangNop .bn-qr-nut { gap:6px; } #bangNop .bn-qr-nut .nut { min-height:36px; padding:6px 10px; font-size:13.5px; }
#bangNop .bn-qr-xong { min-height:42px; padding:8px 12px; font-size:14.5px; width:100%; justify-content:center; }
#bangNop .bn-lh { margin-top:10px; padding:10px; gap:8px; }
#bangNop .bn-lh-dau { font-size:15px; } #bangNop .bn-lh-dau span { font-size:12.5px; }
#bangNop .bn-cb { padding:8px 10px; gap:8px; } #bangNop .bn-cb .av { width:32px; height:32px; font-size:14px; }
#bangNop .bn-cb .tt b { font-size:14.5px; } #bangNop .bn-cb .tt .nho { font-size:12.5px; }
#bangNop .bn-cb-nut a { min-height:38px; padding:6px 12px; font-size:14px; }
#bangNop .bn-goilai { font-size:13px; }
#bangNop .bn-tom { padding:10px 12px; gap:4px; } #bangNop .bn-tom-ten b { font-size:16px; } #bangNop .bn-tom-tien b.tien-hd { font-size:20px; }
@media (max-width:520px) { #bangNop .bn-qr-than { grid-template-columns:1fr; } #bangNop .bn-qr-anh { width:min(190px, 60vw); height:auto; } #bangNop .bn-qr-xong { font-size:13.5px; padding:8px; gap:5px; } }
.nt-nut.huy { background:#fff; border-color:#ef9a9a; color:#c62828; font-size:14px; } .nt-nut.huy:hover { border-color:#c62828; background:#fdecea; }
  // v70: bảng nộp tiền gọn 5 phần: 1 thông tin + số tiền · 2 lưu ý · 3 tích đã đọc · 4 mã QR (+ Gửi bill) · 5 liên hệ cán bộ phụ trách chốt số (ưu tiên Zalo)
  const tenZ = x => zaloCB(x) ? `<a class="zalo" href="${linkZalo(zaloCB(x))}" target="_blank" rel="noopener" data-ten="${esc(x.ten)}">${ic('message')} ${ds.length === 1 ? 'Zalo nhận số tài khoản' : 'Zalo'}</a>` : '';
  $('bnThan').innerHTML = `<div class="bn-tom">
      <div class="bn-tom-ten"><b>${esc(TC.ten)}</b><span>${esc(TC.ma)} · ${esc(TC.xom)}${TC.khu ? ', ' + esc(TC.khu) : ''}</span></div>
      <div class="bn-tom-tien"><span>Tháng ${esc(k.thang)}</span><b class="tien-hd">${t ? tien(t.tong) : '–'}</b></div></div>
    ${ho ? '<div class="bn-ho">' + ic('user') + '<span>Nộp hộ: khi nhắn cán bộ ghi rõ <b>mã khách hàng và họ tên chủ hộ</b> ở trên.</span></div>' : ''}
    <div class="bn-canh gon"><b><i class=ic data-ic=alert></i> Lưu ý trước khi nộp</b>
        <li>Chuyển đúng <b class="chu-do-dam">${t ? esc(tien(t.tong)) : 'số tiền trên hóa đơn'}</b>, khớp hóa đơn / biên nhận.</li>
        ${pt && pt.tk && pt.tk.chu ? `<li>Quét QR xong, app ngân hàng phải hiện tên <b class="chu-do-dam">${esc(pt.tk.chu)}</b> – khác tên thì <b>dừng lại</b>.</li>` : '<li>Chỉ chuyển cho <b>đúng cán bộ quản lý địa bàn</b> bên dưới.</li>'}
        <li>Nộp xong <b>gửi bill</b> cho nhân viên thu tiền.</li>
    <label class="bn-dongy gon"><input type="checkbox" id="bnDongY"><span>Tôi đã đọc và hiểu các lưu ý trên</span></label>
    ${pt && pt.tk ? '<div class="bn-qr bn-ds khoa" id="bnQR"></div>' : ''}
    <div class="bn-lh bn-ds khoa" id="bnDs">
      <div class="bn-lh-dau">${ic('user')} Cán bộ phụ trách chốt số${pt && pt.sdt && pt.thang ? `<span>thu tháng ${esc(pt.thang)}${pt.thutien ? ' · ngày ' + esc(pt.thutien) : ''}</span>` : ''}</div>
      ${ds.length ? ds.map(x => `<div class="bn-cb"><div class="av">${esc(chuDau(x.ten))}</div><div class="tt"><b>Đ/c ${esc(x.ten)}</b><span class="nho">${esc(x.chucVu)} · ${esc(dinhSdt(x.sdt))}</span></div>
        <div class="bn-cb-nut">${tenZ(x)}<a class="goi2" href="tel:${esc(x.sdt)}" data-ten="${esc(x.ten)}" aria-label="Gọi ${esc(x.ten)}">${ic('phone')} Gọi</a></div></div>`).join('') : '<div class="nho">Chưa có cán bộ phụ trách – vui lòng gọi trạm.</div>'}
      <div class="nho" id="bnChepKQ"></div>
      <a href="#" id="bnGoiLai" class="bn-goilai">Hoặc để nhân viên gọi lại cho tôi</a>
  $('bnDongY').onchange = () => { const on = $('bnDongY').checked; $('bnDs').classList.toggle('khoa', !on); if ($('bnQR')) $('bnQR').classList.toggle('khoa', !on); };
// v70: nội dung chuyển khoản = HỌ TÊN CHỦ HỘ (không dấu) + 4 số cuối mã KH + tháng, tối đa 35 ký tự (tên dài → viết tắt họ / tên đệm)
function noiDungCK(ten, ma, thang) {
  const so4 = String(ma).replace(/\D/g, '').slice(-4), m = String(thang).match(/^(\d{1,2})\/(\d{4})$/), duoi = ' ' + so4 + ' T' + (m ? m[1].padStart(2, '0') + ' ' + m[2] : String(thang).replace(/\D+/g, ' ').trim());
  const tu = String(ten || '').replace(/\([^)]*\)/g, ' ').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').trim().split(/\s+/).filter(Boolean);
  const toiDa = 35 - duoi.length;
  for (let i = 0; i < tu.length - 1 && tu.join(' ').length > toiDa; i++) tu[i] = tu[i][0];
  return (tu.join(' ').slice(0, toiDa).trim() + duoi).trim();
}
  const soTien = Math.round(t.tong), th = String(k.thang), nd = noiDungCK(tenHo, ma, th);
  const gon = [['Người nhận', tk.chu, '#c62828'], ['Tài khoản', tk.nh + ' · ' + tk.stk.replace(/(\d{4})(?=\d)/g, '$1 ')], ['Số tiền', tien(soTien), '#c62828'], ['Nội dung', nd]];
  el.innerHTML = `<div class="bn-qr-dau">${ic('qr')} Quét mã QR <span>Đ/c ${esc(ten)}</span></div>
      <div class="bn-qr-tt">${gon.map(([a, b, m]) => `<span>${esc(a)}</span><b${m ? ' style="color:' + m + ';font-weight:800"' : ''}>${esc(b)}</b>`).join('')}</div></div>
    <div class="bn-qr-nut"><button type="button" class="nut phu nho-nut" id="bnTaiQR">${ic('download')} Tải QR</button><button type="button" class="nut phu nho-nut" id="bnChepSTK">${ic('copy')} Chép số TK</button></div>
    <button type="button" class="nut bn-qr-xong" id="bnDaCK">${ic('receipt')} Gửi bill thanh toán cho nhân viên thu tiền</button><div class="nho" id="bnQRKQ" style="text-align:center"></div>`;
  $('bnDaCK').onclick = () => {
    // v70: ghi phiếu "Quét mã QR" + báo Telegram cán bộ, rồi mở Zalo cán bộ để khách gửi ảnh chụp bill
    const z = zaloCB(pt), link = z ? (/^https:/.test(z) ? z : URL_ZALO + z) : '';
    if (link) { try { window.open(link, '_blank', 'noopener'); } catch (e) {} }
    $('bnDaCK').disabled = true; ghiTC('Nộp tiền – gửi bill QR', ma);
    goi('ghiNopTien', { ma: ma, cach: 'Chuyển khoản QR', canBo: ten, ho: false }).then(() => {
      $('bnQRKQ').innerHTML = '<b>✓ Đã báo Đ/c ' + esc(ten) + '</b>.' + (link ? ' Zalo của Đ/c ' + esc(ten) + ' đang mở – <b>gửi ảnh chụp bill chuyển khoản</b> vào đó.' : ' Quý khách gửi ảnh chụp bill qua Zalo cho Đ/c ' + esc(ten) + '.') + ' Cán bộ kiểm tra và xác nhận thu.';
    }).catch(e => { $('bnDaCK').disabled = false; $('bnQRKQ').textContent = String(e); });
  };
    if (ND && ND.vaitro === 'ld') return baoNhanh('Tài khoản Lãnh đạo chỉ xem số liệu.');
    // v70: đổi ngay trên màn hình, máy chủ ghi ngầm; lỗi thì trả lại
    const cu6 = x[6], cu7 = x[7], ky = TTH.thang;
    x[6] = moi ? 'da' : 'chua'; x[7] = moi && ND ? ND.ten + ' · vừa xong' : ''; hienTTH();
    goiNB('danhDauThuTien', ky, [ma], moi).catch(e => { x[6] = cu6; x[7] = cu7; hienTTH(); $('loiTT').textContent = e; baoLoi('Chưa ghi được: ' + e); });
      <div class="nt-ct"><span><i class=ic data-ic=clock></i> ${esc(x.tg)}</span><span>Hình thức: ${[...new Set(String(x.cach || '').split(', ').filter(Boolean).map(c => c === 'Chuyển khoản QR' ? 'qr' : c === 'Gọi' ? 'goi' : 'zl'))].map(k => `<b class="nt-ht ${k}">${k === 'qr' ? ic('qr') + ' Quét mã QR' : k === 'goi' ? ic('phone') + ' Gọi điện' : ic('message') + ' Nhắn Zalo'}</b>`).join(' ')}</span>${x.canbo ? `<span class="${x.cuaToi ? 'nt-toi' : ''}"><i class=ic data-ic=user></i> Giao cho: <b>${esc(x.canbo)}</b>${x.cuaToi ? ' (bạn)' : ''}</span>` : '<span><i class=ic data-ic=user></i> Chưa giao cán bộ</span>'}</div>
        <button type="button" class="nt-nut chua huy" data-v="0"><i class=ic data-ic=xCircle></i> Chưa nộp – Hủy phiếu</button>
  // v70: bấm là đổi NGAY trên màn hình (máy chủ ghi ngầm, lỗi thì trả lại + báo). "Chưa nộp – Hủy phiếu" = hủy luôn (ẩn khỏi danh sách). Lãnh đạo chỉ xem.
  $$('#dsNT .nt-nut').forEach(b => b.onclick = () => {
    if (ND && ND.vaitro === 'ld') return baoNhanh('Tài khoản Lãnh đạo chỉ xem số liệu.');
    const the = b.closest('.nt-the'), dong = Number(the.dataset.dong), x = NT.find(y => y.dong === dong), daNop = b.dataset.v === '1';
    const truoc = { daNop: x.daNop, nv: x.nv, tgxn: x.tgxn };
    if (daNop) {
      if (x.daNop) { the.querySelector('.nt-nhac').innerHTML = 'Phiếu này <b>đang là Đã nộp</b>. Ghi nhầm thì bấm <b>Chưa nộp – Hủy phiếu</b>.'; return; }
      x.daNop = true; x.nv = ND ? ND.ten : ''; x.tgxn = 'vừa xong'; hienNT();
      const viec = goiNB('xacNhanNopTien', dong, true).then(r => { x.daNop = r.daNop; x.nv = r.nv; x.tgxn = r.tgxn; ghiTC('Xác nhận đã nộp tiền', x.ma); hienNT(); })
        .catch(e => { Object.assign(x, truoc); hienNT(); baoLoi('Chưa ghi được Đã nộp cho ' + x.ten + ': ' + e); throw e; });
      baoHoanTac('Đã ghi: ' + x.ten + ' – ĐÃ NỘP tháng ' + (x.thang || '–'), () => viec.then(() => goiNB('xacNhanNopTien', dong, false)).then(r => { x.daNop = r.daNop; x.nv = r.nv; x.tgxn = r.tgxn; ghiTC('Hoàn tác xác nhận nộp tiền', x.ma); hienNT(); }));
    } else {
      const vt = NT.indexOf(x); NT.splice(vt, 1); hienNT();
      const traLai = () => { if (NT.indexOf(x) < 0) { NT.splice(Math.min(vt, NT.length), 0, x); Object.assign(x, truoc); hienNT(); } };
      const viec = goiNB('huyPhieuNopTien', dong).then(() => ghiTC('Hủy phiếu nộp tiền', x.ma)).catch(e => { traLai(); baoLoi('Chưa hủy được phiếu của ' + x.ten + ': ' + e); throw e; });
      baoHoanTac('Đã hủy phiếu: ' + x.ten + ' tháng ' + (x.thang || '–') + (truoc.daNop ? ' (tháng về chưa nộp)' : ''), () => viec.then(() => goiNB('xacNhanNopTien', dong, truoc.daNop)).then(r => { Object.assign(x, { daNop: r.daNop, nv: r.nv, tgxn: r.tgxn }); if (NT.indexOf(x) < 0) NT.splice(Math.min(vt, NT.length), 0, x); ghiTC('Hoàn tác hủy phiếu', x.ma); hienNT(); }));
